local function trailTeleport(newPos)local r=hr()if not r then return end local startPos=r.Position local dist=(newPos-startPos).Magnitude local steps=math.max(1,math.floor(dist/2.5))local baseCol=PCN=="yellow"and Color3.fromRGB(255,220,40)or PCN=="red"and Color3.fromRGB(255,60,60)or PCN=="orange"and Color3.fromRGB(255,150,40)or PCN=="blue"and Color3.fromRGB(60,120,255)or PCN=="purple"and Color3.fromRGB(180,60,255)or PCN=="pink"and Color3.fromRGB(255,120,200)or PCN=="white"and Color3.fromRGB(255,255,255)or PCN=="black"and Color3.fromRGB(40,40,40)or Color3.fromRGB(0,255,136)for i=1,steps do local t=i/steps local p=startPos+(newPos-startPos)*t+Vector3.new(0,math.random(-1,1),0)local tile=Instance.new("Part")tile.Size=Vector3.new(1.5,0.2,1.5)tile.Position=p tile.Anchored=true tile.CanCollide=false tile.CanQuery=false tile.Material=Enum.Material.Neon if PCN=="rainbow"then tile.Color=Color3.fromHSV((tick()+i*0.1)%1,1,1)else tile.Color=baseCol end tile.Transparency=0.2 tile.Parent=W table.insert(WO2,tile)task.spawn(function()T:Create(tile,TweenInfo.new(2),{Size=Vector3.new(0.1,0.05,0.1),Transparency=1}):Play()task.wait(2)if tile.Parent then tile:Destroy()end end)end r.CFrame=CFrame.new(newPos)end
local function createPortal(special)local root=hr()if not root then return nil end local look=root.CFrame.LookVector if look.Magnitude<0.01 then look=Vector3.new(0,0,-1)end local pos=root.Position+look*20 local cf=CFrame.new(pos,pos+look)*CFrame.Angles(0,math.rad(90),0)local baseCol=special and Color3.fromRGB(255,220,40)or PCN=="yellow"and Color3.fromRGB(255,220,40)or PCN=="red"and Color3.fromRGB(255,60,60)or PCN=="orange"and Color3.fromRGB(255,150,40)or PCN=="blue"and Color3.fromRGB(60,120,255)or PCN=="purple"and Color3.fromRGB(180,60,255)or PCN=="pink"and Color3.fromRGB(255,120,200)or PCN=="white"and Color3.fromRGB(255,255,255)or PCN=="black"and Color3.fromRGB(40,40,40)or PCN=="rainbow"and Color3.fromRGB(255,0,255)or Color3.fromRGB(0,255,136)local p=Instance.new("Part")p.Name="Portal"p.Shape=Enum.PartType.Cylinder p.Size=Vector3.new(1,10,10)p.CFrame=cf p.Anchored=true p.CanCollide=false p.CanTouch=false p.CanQuery=false p.Material=Enum.Material.Neon p.Color=baseCol p.Transparency=0.15 p.Parent=W local inner=Instance.new("Part")inner.Name="Inner"inner.Shape=Enum.PartType.Cylinder inner.Size=Vector3.new(0.8,6,6)inner.CFrame=cf inner.Anchored=true inner.CanCollide=false inner.CanTouch=false inner.CanQuery=false inner.Material=Enum.Material.Neon inner.Color=baseCol inner.Transparency=0.4 inner.Parent=p local pl=Instance.new("PointLight")pl.Range=20 pl.Brightness=3 pl.Shadows=false pl.Color=baseCol pl.Parent=p local bb=Instance.new("BillboardGui")bb.Size=UDim2.new(0,220,0,50)bb.StudsOffset=Vector3.new(0,8,0)bb.AlwaysOnTop=true bb.Parent=p local lbl=Instance.new("TextLabel")lbl.Size=UDim2.new(1,0,1,0)lbl.BackgroundTransparency=1 if special then lbl.Text=L("specialPortal")else lbl.Text=getLabel()end lbl.TextColor3=baseCol lbl.Font=Enum.Font.GothamBold lbl.TextSize=18 lbl.TextStrokeTransparency=0.3 lbl.Parent=bb local snd=Instance.new("Sound")snd.SoundId="rbxassetid://9118823101"snd.Looped=true snd.Volume=0.4 snd.Parent=p pcall(function()snd:Play()end)local conn conn=R.He