local function blackholeEffect()local r=hr()if not r then return end local pos=r.Position+r.CFrame.LookVector*60 local bh=Instance.new("Part")bh.Shape=Enum.PartType.Ball bh.Size=Vector3.new(8,8,8)bh.Position=pos bh.Anchored=true bh.Material=Enum.Material.Neon bh.Color=Color3.fromRGB(0,0,0)bh.Parent=W table.insert(WO,bh)local pl=Instance.new("PointLight")pl.Range=60 pl.Brightness=5 pl.Color=Color3.fromRGB(100,0,255)pl.Parent=bh local ring=Instance.new("Part")ring.Shape=Enum.PartType.Cylinder ring.Size=Vector3.new(1,16,16)ring.CFrame=CFrame.new(pos)*CFrame.Angles(0,0,math.rad(90))ring.Anchored=true ring.CanCollide=false ring.Material=Enum.Material.Neon ring.Color=Color3.fromRGB(100,0,255)ring.Transparency=0.3 ring.Parent=W table.insert(WO,ring)local conn conn=R.Heartbeat:Connect(function(dt)if ring.Parent then ring.CFrame=ring.CFrame*CFrame.Angles(math.rad(dt*180),0,0)end local rr=hr()if rr and bh.Parent then local dir=(bh.Position-rr.Position).Unit local dist=(bh.Position-rr.Position).Magnitude if dist<150 then rr.CFrame=rr.CFrame+dir*(dt*30)end end end)table.insert(WL2,conn)B("BLACKHOLE",Color3.fromRGB(100,0,255))end
