local function handleCommand(text)text=text:gsub("^%s+",""):gsub("%s+$","")if text==""then return end local lower=text:lower()local x,y,z=lower:match("^(-?%d+)%s+(-?%d+)%s+(-?%d+)$")if x and y and z then local r=hr()if r then local rx=tonumber(x)+(math.random()<0.5 and-1 or 1)*math.random(100,1000000)local rz=tonumber(z)+(math.random()<0.5 and-1 or 1)*math.random(100,1000000)local ry=tonumber(y)+math.random(0,50)trailTeleport(Vector3.new(rx,ry,rz))if currentPortal and currentPortal.Parent and not isSpecial then local s=Instance.new("Sound")s.SoundId="rbxassetid://9118823101"s.Volume=0.5 s.Parent=currentPortal s:Play()currentPortal:Destroy()currentPortal=nil if portalConn then portalConn:Disconnect()portalConn=nil end end B("ТП",Color3.fromRGB(120,255,180))end return end if lower=="random"then local r=hr()if r then local a=math.random()*math.pi*2 local d=math.random(50,200)local nx=r.Position.X+math.cos(a)*d local nz=r.Position.Z+math.sin(a)*d trailTeleport(Vector3.new(nx,gr(nx,nz),nz))end return end local pn=lower:match("^player%s+(.+)$")if pn then local t=findPlayer(pn)if t and t.Character then local tr=t.Character:FindFirstChild("HumanoidRootPart")if tr then trailTeleport(tr.Position+Vector3.new(0,3,0))B("ТП",Color3.fromRGB(120,255,180))end else TT("Нет игрока",Color3.fromRGB(255,100,100))end return end local nn=lower:match("^npc%s+(.+)$")if nn then local part=findByName(nn)if part then trailTeleport(part.Position+Vector3.new(0,3,0))B("ТП",Color3.fromRGB(120,255,180))else TT("Нет NPC",Color3.fromRGB(255,100,100))end return end local inm=lower:match("^item%s+(.+)$")if inm then local part=findByName(inm)if part then trailTeleport(part.Position+Vector3.new(0,3,0))B("ТП",Color3.fromRGB(120,255,180))else TT("Нет предмета",Color3.fromRGB(255,100,100))end return end local gal=lower:match("^galactic%s+([a-z])%-(%d+)$")if gal then local letter,num=gal:match("^([a-z])%-(%d+)$")local n=tonumber(num)if n>=1 and n<=999 then PendingName="GALACTIC "..letter:upper().."-"..n galacticWorld(letter,n)PendingName=nil return end end if lower=="home"then PendingName="ДОМ"homeWorld()PendingName=nil return end if lower=="main"then PendingName="ГЛАВНЫЙ МИР"cmAll()PendingName=nil return end if lower=="clear"then cmAll()return end if lower=="clear world"then clearWorld()return end if lower=="clear effect"then clearEffects()return end if lower=="clear weather"then clearWeatherCmd()return end if colorMap[lower]then PCN=lower if currentPortal and currentPortal.Parent then currentPortal.Color=colorMap[lower]local inner=currentPortal:FindFirstChild("Inner")if inner then inner.Color=colorMap[lower]end local pl=currentPortal:FindFirstChildOfClass("PointLight")if pl then pl.Color=colorMap[lower]end end B(string.upper(lower),Color3.fromRGB(120,255,180))return end if lower=="rainbow"then PCN="rainbow"B("RAINBOW",Color3.fromHSV(math.random(),1,1))return end if lower:sub(1,6)=="world "then local wname=lower:sub(7)local map={yellow={"yellow","ЖЁЛТЫЙ МИР"},black={"black","ЧЁРНЫЙ МИР"},red={"red","КРАСНЫЙ МИР"},orange={"orange","ОРАНЖЕВЫЙ МИР"},green={"green","ЗЕЛЁНЫЙ МИР"},blue={"blue","СИНИЙ МИР"},purple={"purple","ФИОЛЕТОВЫЙ МИР"},pink={"pink","РОЗОВЫЙ МИР"},white={"white","БЕЛЫЙ МИР"},toxic={"toxic","ТОКСИЧНЫЙ МИР"},paint={"paint","РАЗНОЦВЕТНЫЙ МИР"},rainbow={"rainbow","РАДУЖНЫЙ МИР"},mountains={"mountains","ГОРНЫЙ МИР"},caves={"caves","ПЕЩЕРНЫЙ МИР"},unicorn={"unicorn","ЕДИНОРОЖИЙ МИР"},cosmos={"cosmos","КОСМОС"},city={"city","ГОРОД"},["67"]={"67","МИР 67"},ufo={"ufo","НЛО"}}if map[wname]then PendingName=map[wname][2]if wname=="yellow"then yellowWorld()elseif wname=="black"then blackWorld()elseif wname=="toxic"then toxicWorld()elseif wname=="paint"then paintWorld()elseif wname=="rainbow"then rainbowWorld()elseif wname=="mountains"then mountainsWorld()elseif wname=="caves"then cavesWorld()elseif wname=="unicorn"then unicornWorld()elseif wname=="cosmos"then cosmosWorld()elseif wname=="city"then cityWorld()elseif wname=="67"then world67()elseif wname=="ufo"then if Progress.wv.ufo then ufoInterior()else TT("НЛО не открыт",Color3.fromRGB(255,100,100))end elseif cwData[wname]then colorWorld(wname)end PendingName=nil return else TT("Нет мира: "..wname,Color3.fromRGB(255,100,100))return end end if lower:sub(1,8)=="weather "then local w=lower:sub(9)if w=="snow"then snowWeather()elseif w=="desert"then desertWeather()elseif w=="lava"then lavaWeather()elseif w=="forest"then forestWeather()elseif w=="night"then nightWeather()elseif w=="day"then dayWeather()elseif w=="sunset"then sunsetWeather()elseif w=="off"then clearWeatherCmd()end return end if lower:sub(1,7)=="effect "then local e=lower:sub(8)if e=="classic"then classicEffect()elseif e=="rainbow"then rainbowEffect()elseif e=="gravity"then gravityEffect()elseif e=="meteor"then meteorEffect()elseif e=="fireworks"then fireworksEffect()elseif e=="blackhole"then blackholeEffect()elseif e=="off"then clearEffects()end return end TT("Нет: "..text,Color3.fromRGB(255,100,100))end
